// Women in Tech — Series Five. Copy is final; art is generated from real photographs.
// Hand-curated (not auto-generated). `front`/`back` are written by the publish step —
// do not hand-edit those two fields.
//
// The brief: 180 years of women who built the thing, from the first published algorithm
// to the people auditing models today. Weighted, like every set here, toward those whose
// work was given away.
//
// On the house no-duplicates rule: it holds. Fifteen women are already carded in Series
// Two, Three and Four (Radia Perlman, Dorothy Denning, Katie Moussouris, Fei-Fei Li and
// the rest), so they are not repeated here — `alreadyCarded` below lists them and the
// roster page links them, because a set like this looking as though it forgot Perlman
// would be worse than the duplication.
//
// Series One, for the record, has forty-seven cards and no women on any of them. That is
// the argument for this set, and it is not a flattering one.
//
// Every scouting report is factual and checkable. No invented quotes: `note` is editorial
// voice, not attribution.

import type { RosterEntry, Rarity, Status, Source } from './roster.ts';
import { rarityLabel, statusLabel } from './roster.ts';

export type { Rarity, Status, Source };
export { rarityLabel, statusLabel };

export type Builder = RosterEntry & {
  /**
   * Skill stack for the card back, 0-100, scoped to this series. Spanning Lovelace to
   * Gebru means the usual axes do not travel, so this set rates depth, whether they were
   * first, how much they gave away, and what changed after. Judgements, not sourced facts.
   */
  technical: number;
  pioneering: number;
  openness: number;
  influence: number;
  note: string;
};

