export const totalPlanned = 50;

export const lockedCount = builders.filter((b) => b.status === 'locked').length;
export const draftedCount = builders.filter((b) => b.status !== 'candidate').length;
export const illustratedCount = builders.filter((b) => Boolean(b.front)).length;

export const featuredBuilders = builders.filter((b) => b.status === 'locked').slice(0, 6);

export function getBuilder(slug: string) {
  return builders.find((b) => b.slug === slug);
}

export type PortraitCredit = {
  credit: string;
  license: string;
  licenseUrl?: string;
  sourceUrl?: string;
};

type RefRow = { slug: string; ref?: (PortraitCredit & { url?: string }) | null };

/**
 * Photographer credits, written by scripts/women-refs.mjs. Same likeness rule as
 * Series Three and Four: painted from an identified photograph, or no face at all.
 */
import refs from '../../data/women-references.json' with { type: 'json' };

export function getPortraitCredit(slug: string): PortraitCredit | undefined {
  const row = (refs as RefRow[]).find((r) => r.slug === slug);
  if (!row?.ref) return undefined;
  const { credit, license, licenseUrl, sourceUrl } = row.ref;
  return { credit, license, licenseUrl, sourceUrl };
}
